p=argparse.ArgumentParser();p.add_argument('--output',required=True,type=Path);p.add_argument('--url');a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1440,'height':1000},reduced_motion='reduce');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(a.url or (root/'SkyMusicStudio_Standalone.html').as_uri());page.locator('.card-play').first.click();assert page.locator('#musicWorkbench').is_visible()
 report=page.evaluate('''()=>{const {Music:M,mw}=window.SKY_MUSIC_TEST;const assert=(v,m)=>{if(!v)throw Error(m)};const c=M.blank();c.tempoMap=[{tick:0,bpm:120},{tick:960,bpm:60}];for(const t of [0,250,960,1500,4000])assert(Math.abs(M.msTick(c,M.tickMs(c,t))-t)<1e-8,'tempo inverse');assert(M.tickMs(c,1920)===1500,'tempo segments');c.meterMap=[{tick:0,numerator:4,denominator:4},{tick:3840,numerator:6,denominator:8}];assert(M.positionTick(c,3)===6720,'compound meter');assert(M.barPosition(c,6720).bar===3,'bar position');const legacy=mw.project.composition,compiled=M.compile(legacy);for(const n of legacy.notes){const e=compiled.find(x=>x.id===n.id);assert(Math.abs(e.timeMs-n.originalMs.start)<1e-7&&Math.abs(e.durationMs-n.originalMs.duration)<1e-7,'legacy timing')}const id=c.tracks[0].id;c.notes=[{id:'a',trackId:id,pitch:61,startTick:0,durationTicks:480,soundTicks:432,gate:.9,velocity:45},{id:'b',trackId:id,pitch:64,startTick:0,durationTicks:960,soundTicks:960,gate:1,velocity:110}];c.tracks.push({id:'other',name:'伴奏',instrument:'offline-harp',volume:.6,mute:false,solo:false});c.notes.push({id:'c',trackId:'other',pitch:40,startTick:960,durationTicks:1440,soundTicks:1440,gate:1,velocity:80});const imported=M.fromMIDI(M.midiBytes(c).buffer);assert(imported.notes.length===3,'midi count');assert(imported.tracks.length===2,'midi tracks');assert(imported.notes.some(n=>n.pitch===61&&n.velocity===45&&n.soundTicks===432),'midi pitch duration');assert(imported.tempoMap[1].tick===960&&imported.tempoMap[1].bpm===60,'midi tempo');assert(imported.meterMap[1].numerator===6,'midi meter');const xml='<score-partwise><part-list><score-part id="P1"><part-name>Piano</part-name></score-part></part-list><part id="P1"><measure number="1"><attributes><divisions>3</divisions><time><beats>4</beats><beat-type>4</beat-type></time></attributes><direction><sound tempo="90"/></direction><note><pitch><step>C</step><alter>1</alter><octave>4</octave></pitch><duration>1</duration><voice>1</voice><type>eighth</type><time-modification><actual-notes>3</actual-notes><normal-notes>2</normal-notes></time-modification><tie type="start"/></note><note><pitch><step>C</step><alter>1</alter><octave>4</octave></pitch><duration>1</duration><voice>1</voice><tie type="stop"/></note><note><rest/><duration>1</duration><voice>1</voice></note></measure></part></score-partwise>';const x=M.fromXML(xml);assert(x.notes[0].pitch===61&&x.notes[0].durationTicks===320&&x.rests.length===1,'XML precise');assert(x.notes[0].tieNext===x.notes[1].id&&M.compile(x).length===1,'tie playback');const digits=M.parseNumbers('1/8 [1+3+5]/4 0/8 #4/8. 5/8t',c,id,0);assert(digits.notes.length===6&&digits.rests.length===1,'number grammar');let rejected=false;try{M.parseNumbers('1/8 bad',c,id,0)}catch(e){rejected=true}assert(rejected,'invalid number syntax');const sky=M.skyPreview(c);assert(sky.unresolved>0,'sky keeps incompatible');return {legacyNotes:legacy.notes.length,tempoInverse:true,midiTracks:imported.tracks.length,xmlTupletsTies:true}}''')
 page.locator('#musicEdit').click();assert page.locator('#musicWorkbench').get_attribute('class').find('music-editing')>=0;page.locator('#musicCalibrate').click();assert page.evaluate('window.SKY_MUSIC_TEST.mw.project.composition.calibrated')
 original=page.evaluate('JSON.stringify(window.SKY_MUSIC_TEST.mw.original)')
