 page.locator('[data-bottom=numbers]').click();page.locator('#musicNumbers').fill('1/8 [1+3+5]/4 0/8');page.locator('[data-music-action=previewNumbers]').click();page.locator('[data-music-action=applyNumbers]').click();assert page.evaluate('window.SKY_MUSIC_TEST.mw.project.composition.notes.length')==7
 page.locator('[data-bottom=sky]').click();page.locator('[data-music-action=previewSky]').click();assert '个起音' in page.locator('#musicSkyReport').inner_text();page.screenshot(path=str(a.output/'editor.png'))
