 # Cancel restores the source and playback position.
 page.locator('#musicEdit').click();page.locator('#discardChanges').click();assert page.locator('#musicWorkbench').is_visible();assert 'music-editing' not in page.locator('#musicWorkbench').get_attribute('class');assert page.evaluate('JSON.stringify(window.SKY_MUSIC_TEST.mw.project)')==original
 # New project parameters are explicit, defaulted, and saved as new formats.
 page.locator('[data-music-action=back]').click();page.locator('#newSongBtn').click();assert page.locator('#createMusicBpm').input_value()=='120';page.locator('#createTitle').fill('乐理工作台测试');page.locator('#createConfirm').click();assert page.locator('#musicWorkbench').is_visible()
 page.locator('[data-music-action=keymap]').click();page.locator('#musicKeymapRows button').first.click();page.keyboard.press('u');page.locator('#musicKeymapRows input').first.fill('61');page.locator('#musicDialogApply').click();page.locator('#musicRollViewport').focus();page.keyboard.press('u');assert page.evaluate('window.SKY_MUSIC_TEST.musicComposition().notes[0].pitch')==61
